﻿﻿﻿'use strict';

function createMainCharacter(_x) {
	if (_x?.class)
		return createCharacter(getCharacterJSON(_x.class));
	return createCharacter(getCharacterJSON(__account.characters.find(x => x.selected)?.class ?? 'warrior'));
}
function getCharacterColor(_class) {
	switch(_class) {
		case 'warrior':
			return '#762c20';
		case 'archer':
			return '#CD7F32';
		case 'thief':
			return '#191970';
		case 'cyclops':
			return '#36454F';
		case 'werewolf':
			return '#54444d';
		case 'druid': 
			return '#228B22';
		case 'wizard': 
			return '#E4D00A';
	}
	return '#f7f7f7';
}
function getCharacterChatColor(_class) {
	switch(_class) {
		case 'warrior':
			return '#ff6c00dd';
		case 'archer':
			return 'darkgoldenrod';
		case 'thief':
			return '#00c4ffdd';
		case 'cyclops':
			return '#36454F';
		case 'werewolf':
			return '#7393B3';
		case 'druid': 
			return '#228B22';
		case 'wizard': 
			return '#E4D00A';
	}
	return '#f7f7f7';
}
