function summonShadowClone(_char, _force) {
	if(episode.pvp || episode.dungeon)
		return;
	const _currentClone = episode.enemies?.find(x => 
		x.key === 'ShadowClone' && x.owner === _char);
	if (_currentClone) {
		_currentClone.lifeTime.from = _gameTick;
		return;
	}
	if(!_force && (episode.dungeon || episode.pvp) && mainCharacter !== _char)
		return;
	const _shadowClone = _store.getMainCharacter(null, {
		key: 'ShadowClone',
		class: 'thief',
		name: 'Shadow Clone'
	});
	_shadowClone.addObject({
		key: 'invisiblesmoke',
		position: 'middle'
	});
	_shadowClone.addObject({
		key: 'shadowfront',
		position: 'middle-bottom'
	});
	delete _shadowClone.animations.air2;
	_shadowClone.enemy = _char.enemy;
	_shadowClone.main = false;
	_shadowClone.id = 10003;
	_shadowClone.friendly = _char.friendly;
	_shadowClone.immunities = ['shadow'];
	_shadowClone.class = 'minion';
	_shadowClone.setAutoMode(2);
	_shadowClone.skipHealthBar = true;
	_shadowClone.noCC = true;
	_shadowClone.sight = 200;
	_shadowClone.dmgTaken = true;
	_shadowClone.health = _shadowClone.maxHP = 1;
	_shadowClone.owner = _char;
	_shadowClone.pickRandomAttack();
	_shadowClone.direction = _char.direction;
	_shadowClone.lifeTime = {
		from: _gameTick,
		ms: _allBuffs.rage.gain.find(x => x.level === 3)?.ms ?? 10000,
		do: function () {
			_shadowClone.relatedObjects.forEach(x => {
				if (x.key === 'shadowfront') {
					x.repeat = false;
					x.remove = true
				}
			});
			_shadowClone.setAutoMode(0);
			_shadowClone.animate('fade', 1);
			episode.enemies?.filter(x => x.autoTarget === _shadowClone)?.forEach(
				x => x.autoTarget = _char
			);
		}
	};
	_shadowClone.yPosition = MathRound(_char.yPosition - (getGroundHeight() / 6));
	if (_shadowClone.yPosition < 0)
		_shadowClone.yPosition = MathRound(_char.yPosition + (getGroundHeight() / 6));
	_shadowClone.left = _char.left + platformX;
	_shadowClone.left -= (_char.direction !== _char.defaultDirection ? 1 : -1) * MathRound((_shadowClone.WIDTH / 2) - 2);
	if (_shadowClone.left < minLeft)
		_shadowClone.left = minLeft;
	else if ((_shadowClone.left + (_shadowClone.WIDTH / 2)) > (_canvas.width + platformX))
		_shadowClone.left = _canvas.width + platformX - MathRound(_shadowClone.WIDTH / 2);
	episode.enemies.push(_shadowClone);
	_shadowClone.addBuff({ key: 'rage', level: 3 });
	if(episode.dungeon || episode.pvp)
	{
		//_shadowClone.socketId = (episode.enemies.filter(x => x.socketId < 1000).map(x => x.socketId).sort().slice(-1)[0] ?? 0) + 1;
		_shadowClone.station = mainCharacter.socketId;
		//_shadowClone.getNewStatus(1, 2);
	}
}

